Fail-open vs fail-closed: the same authorisation check, twice.

# WRONG - the exception skips the check and execution continues
def can_read(user, doc):
    try:
        return acl.check(user, doc)   # network call
    except Exception:
        return True                   # "don't break prod in an outage"

# RIGHT - the error path denies, loudly
def can_read(user, doc):
    try:
        return acl.check(user, doc)
    except Exception as e:
        log.error("acl unavailable", exc_info=e)
        raise AccessDenied("denied")

# Also fail-open: a bare except-pass, a default-allow firewall.
